parameters.functionScript:
if (Inputs.trigger === undefined || Inputs.body === undefined || Inputs.projects === undefined || Inputs.members === undefined || Inputs.clients === undefined || Inputs.posts === undefined) return;

const trig = Inputs.trigger || {};
const body = Inputs.body || {};
const recordId = trig.recordId || body.recordId || body.id || (body.record && body.record.id) || '';

const ptrId = function (value) {
  if (typeof value === 'string') return value;
  if (value && value.id) return value.id;
  if (value && value.objectId) return value.objectId;
  return '';
};

const project = (Inputs.projects || []).find(function (p) { return p.id === recordId; });

if (!project) {
  Outputs.posted = false;
  Outputs.reason = 'project not found';
  Outputs.skip();
  return;
}

if (project.status !== 'Done') {
  Outputs.posted = false;
  Outputs.reason = 'status is not Done';
  Outputs.skip();
  return;
}

const oldStatus = body.previousStatus || (body.previousRecord && body.previousRecord.status) || (body.before && body.before.status) || null;
if (oldStatus === 'Done') {
  Outputs.posted = false;
  Outputs.reason = 'was already Done';
  Outputs.skip();
  return;
}

if (oldStatus === null) {
  const already = (Inputs.posts || []).some(function (post) {
    return post.kind === 'system' && ptrId(post.project) === recordId;
  });
  if (already) {
    Outputs.posted = false;
    Outputs.reason = 'already announced';
    Outputs.skip();
    return;
  }
}

const owner = (Inputs.members || []).find(function (m) { return m.id === ptrId(project.owner); });
const client = (Inputs.clients || []).find(function (c) { return c.id === ptrId(project.client); });

let content = 'Project "' + project.name + '"';
if (client) content += ' for ' + client.name;
content += ' is done';
if (owner) content += ' — nice work, ' + owner.name + '!';

Outputs.posted = true;
Outputs.reason = 'posted';
Outputs.content = content;
Outputs.projectId = recordId;
Outputs.post();
